tool.command:
@SHELL_OPTIONS@
## create symlinks to input datasets ln -s '$fasta' input.fasta && ln -s '$taxonomy' input.taxonomy && #if $nameOrCount.ext == "mothur.names": ln -s '$nameOrCount' input.names && #else: ln -s '$nameOrCount' input.count_table && #end if
echo 'cluster.split( fasta=input.fasta, taxonomy=input.taxonomy, #if $nameOrCount.ext == "mothur.names": name=input.names, #else: count=input.count_table, #end if taxlevel=$taxlevel, method=$condmethod.method, #if $condmethod.method == "opti": metric=$condmethod.metric, initialize=$condmethod.initialize, delta=$condmethod.delta, iters=$condmethod.iters, #end if classic=$classic, #if float($cutoff) > 0.0: cutoff=$cutoff, #end if precision=$precision, #if $dist == "true": dist=$dist, #end if cluster=$cluster, runsensspec=$runsensspec, processors='\${GALAXY_SLOTS:-8}' )' | sed 's/ //g' ## mothur trips over whitespace | mothur | tee mothur.out.log
